import{calculator,CalcError,has,pos,frac,nonneg,ceilSafe,dflt,num,appliance,bool}from './core.js?ver=f6b0e0a822';import{sumLoads,loadRows}from './sizing.js?ver=f6b0e0a822';function yieldFor(i,d){if(has(i,'yield_kwh_per_kwp_day')){return{yield_kwh_per_kwp_day:pos(i,'yield_kwh_per_kwp_day'),yield_source:'input'};}
if(i.city){const c=d?.cities?.[String(i.city).trim().toLowerCase()];if(!c||!(c.yield>0))throw new CalcError('city_unknown','city');return{yield_kwh_per_kwp_day:c.yield,yield_source:'city'};}
const psh=pos(i,'psh',undefined,'yield_or_city_or_psh_required');const pr=frac(i,'pr',dflt(d,'pr'));return{yield_kwh_per_kwp_day:psh*pr,yield_source:'psh',psh,pr};}
export const solar_size=calculator((i,d)=>{let daily_kwh;const echo={};if(has(i,'daily_kwh'))daily_kwh=pos(i,'daily_kwh');else{echo.monthly_units=pos(i,'monthly_units',undefined,'usage_required');daily_kwh=echo.monthly_units/dflt(d,'days_per_month');}
const y=yieldFor(i,d);const panel_w=pos(i,'panel_w',dflt(d,'panel_w'));const kw=daily_kwh/y.yield_kwh_per_kwp_day;const panels=ceilSafe((kw*1000)/panel_w);const installed_kw=(panels*panel_w)/1000;return{...echo,daily_kwh,...y,panel_w,kw,panels,installed_kw,roof_m2:panels*dflt(d,'panel_area_m2'),monthly_kwh_estimate:installed_kw*y.yield_kwh_per_kwp_day*dflt(d,'days_per_month'),};});export const solar_battery=calculator((i,d)=>{const night_kwh=pos(i,'night_kwh');const days=pos(i,'days',1);const volts=pos(i,'volts');const dod=frac(i,'dod',dflt(d,'dod_lifepo4'));const inverter_eff=frac(i,'inverter_eff',dflt(d,'inverter_eff_hybrid'));const ah=(night_kwh*1000*days)/(volts*dod*inverter_eff);return{night_kwh,days,volts,dod,inverter_eff,ah,kwh:(ah*volts)/1000};});export const panel_for_12v=calculator((i,d)=>{const ah=pos(i,'ah');const volts=pos(i,'volts');const dod=frac(i,'dod',dflt(d,'dod_lead_acid'));const psh=pos(i,'psh');const charge_eff=frac(i,'charge_eff',dflt(d,'charge_eff_lead_acid'));const pr=frac(i,'pr',dflt(d,'pr'));const panel_w=(ah*volts*dod)/charge_eff/(psh*pr);const sizes=dflt(d,'standard_panel_w');const standard_panel_w=sizes.find((s)=>s>=panel_w-1e-9)??null;const out={ah,volts,dod,psh,pr,charge_eff,panel_w};let fitted_w;if(standard_panel_w !==null){out.standard_panel_w=standard_panel_w;fitted_w=standard_panel_w;}else{out.panels_of_largest=ceilSafe(panel_w/sizes[sizes.length-1]);fitted_w=out.panels_of_largest*sizes[sizes.length-1];}
out.fitted_panel_w=fitted_w;out.charge_hours=(ah*volts*dod)/charge_eff/(fitted_w*pr);out.charge_days=out.charge_hours/psh;const margin=num(i,'margin',{def:dflt(d,'margin'),min:1});out.margin=margin;out.controller_a=(fitted_w/volts)*margin;const controllers=dflt(d,'standard_controller_a');const standard_controller_a=controllers.find((s)=>s>=out.controller_a-1e-9);if(standard_controller_a !==undefined)out.standard_controller_a=standard_controller_a;else out.controller_above_standard_sizes=true;return out;});function solarSystem(daily_kwh,running_w,surge_w,i,d){const y=yieldFor(i,d);const panel_w=pos(i,'panel_w',dflt(d,'panel_w'));const pr=frac(i,'pr',dflt(d,'pr'));const margin=num(i,'margin',{def:dflt(d,'margin'),min:1});const night_hours=nonneg(i,'night_hours',0);let bat=null;let night_kwh=0;if(night_hours>0){night_kwh=(running_w*night_hours)/1000;const volts=pos(i,'battery_v',dflt(d,'battery_v_default'));bat={volts,...solar_battery.raw({night_kwh,volts,dod:i.dod,inverter_eff:i.inverter_eff},d)};}
let array_kwh=daily_kwh;let offgrid={};if(bool(i.off_grid)&&bat){const charge_eff=frac(i,'charge_eff',bat.dod>dflt(d,'dod_lead_acid')?dflt(d,'charge_eff_lifepo4'):dflt(d,'charge_eff_lead_acid'));const load_kwh=Math.max(daily_kwh,night_kwh);array_kwh=load_kwh-night_kwh+night_kwh/(bat.inverter_eff*charge_eff);offgrid={off_grid:true,charge_eff,battery_inverter_eff:bat.inverter_eff,load_kwh,day_kwh:load_kwh-night_kwh};}
const kw_energy=array_kwh/y.yield_kwh_per_kwp_day;const kw_power=running_w/1000/pr;const kw=Math.max(kw_energy,kw_power);const panels=ceilSafe((kw*1000)/panel_w);const installed_kw=(panels*panel_w)/1000;const load_w=running_w*margin;const dc_ac_ratio_max=dflt(d,'dc_ac_ratio_max');const inverter_w=Math.max(load_w,(installed_kw*1000)/dc_ac_ratio_max);const out={daily_kwh,array_kwh,...offgrid,running_w,surge_w,...y,pr,panel_w,margin,kw_energy,kw_power,kw,panels,installed_kw,roof_m2:panels*dflt(d,'panel_area_m2'),monthly_kwh_estimate:installed_kw*y.yield_kwh_per_kwp_day*dflt(d,'days_per_month'),inverter_kw_load:load_w/1000,inverter_kw_array:installed_kw/dc_ac_ratio_max,dc_ac_ratio_max,inverter_w,inverter_kw:inverter_w/1000,inverter_surge_w:surge_w,limited_by:kw_power>kw_energy?'power':'energy',};if(bat)Object.assign(out,{night_hours,night_kwh,battery_v:bat.volts,battery_dod:bat.dod,battery_ah:bat.ah,battery_kwh:bat.kwh});return out;}
export const solar_for_ac=calculator((i,d)=>{const ac=appliance(d,i.ac,'ac');const hours=nonneg(i,'hours',ac.typical_hours_per_day??0);const avg_w=ac.avg_w??ac.running_w;const daily_kwh=(avg_w*hours)/1000;return{ac:i.ac.trim(),ac_name:ac.name,ac_run_w:ac.running_w,ac_start_w:ac.starting_w,ac_avg_w:avg_w,hours,...solarSystem(daily_kwh,ac.running_w,ac.starting_w,i,d)};});export const solar_from_loads=calculator((i,d)=>{const rows=loadRows(i.loads,d);const{running_w,surge_w}=sumLoads(rows);const daily_kwh=rows.reduce((s,r)=>s+r.energy_w*r.qty*r.hours,0)/1000;if(!(daily_kwh>0))throw new CalcError('hours_required','loads');return{appliances:rows.length,...solarSystem(daily_kwh,running_w,surge_w,i,d)};});
export const solar_for_pump=calculator((i,d)=>{const hp=pos(i,'hp');const motor_eff=frac(i,'motor_eff',dflt(d,'motor_eff'));const hours=pos(i,'hours');const pump_w=(hp*dflt(d,'w_per_hp'))/motor_eff;const sys=solarSystem((pump_w*hours)/1000,pump_w,pump_w,i,d);return{hp,motor_eff,hours,pump_w,pump_kw:pump_w/1000,motor_kw:(hp*dflt(d,'w_per_hp'))/1000,...sys,drive_kw:sys.inverter_kw};});
